    const tone = owner[at] === null ? null : owner[at] === 0 ? "1" : owner[at] === 1 ? "2" : "3";
    const last = runs[runs.length - 1];
    if (last && last.tone === tone) last.text += character;
    else runs.push({ tone, text: character });
